mapper.update:
UPDATE tb_task t SET
t.release_time = #{releaseTime},
t.state = #{newState},
t.row_version = t.row_version + 1,
t.modify_time = now()
WHERE t.id = #{id}
  AND t.row_valid = 1
  AND t.state = #{expectedState}
  AND t.row_version = #{expectedRowVersion}

mapper.select:
SELECT MAX(t.sequence_no)
FROM tb_task t
WHERE t.activity_id = #{activityId}
  AND t.phase = #{phase}

SELECT 
FROM tb_task t
WHERE t.activity_id = #{activityId}
  AND t.phase = #{phase}
  AND t.sequence_no = #{sequenceNo}
  AND t.row_valid = 1
ORDER BY t.id ASC

SELECT COUNT(*)
FROM tb_task t
WHERE t.activity_id = #{activityId}
  AND t.phase = #{phase}
  AND t.sequence_no = #{sequenceNo}
